package dev.homecontrol.app;
import org.json.*;
import java.io.IOException;
import java.util.*;

final class LightSchedules {
    static String cron(int hour,int minute,JSONArray days)throws Exception {if(hour<0||hour>23||minute<0||minute>59||days==null||days.length()==0)throw new IOException("请选择有效的时间和重复日期");SortedSet<Integer> selected=new TreeSet<>();for(int i=0;i<days.length();i++){Object v=days.get(i);if(!(v instanceof Number)||((Number)v).intValue()!=((Number)v).doubleValue())throw new IOException("重复日期无效");int day=((Number)v).intValue();if(day<0||day>6)throw new IOException("重复日期无效");selected.add(day);}StringBuilder week=new StringBuilder();for(int day:selected){if(week.length()>0)week.append(',');week.append(day);}return minute+" "+hour+" * * "+(selected.size()==7?"*":week.toString());}
    static JSONObject create(String did,JSONObject in)throws Exception {
        int h=KitchenProgram.integer(in,"hour"),m=KitchenProgram.integer(in,"minute");String time=cron(h,m,in.optJSONArray("days"));if(!(in.opt("on") instanceof Boolean))throw new IOException("请选择开关动作");boolean on=in.getBoolean("on");
        JSONObject setting=new JSONObject().put("enable_timer","1").put("timer_type","0").put("enable_timer_on",on?"1":"0").put("enable_timer_off",on?"0":"1").put("on_time",time).put("off_time",time).put("on_method","set_properties").put("off_method","set_properties").put("on_param",params(did,true)).put("off_param",params(did,false));
        return new JSONObject().put("identify",did).put("st_id",8).put("name",String.format(Locale.ROOT,"家聚 · %02d:%02d %s",h,m,on?"开灯":"关灯")).put("setting",setting).put("authed",new JSONArray().put(did));
    }
    static JSONArray list(Object raw)throws Exception {Object value=FeatureData.unwrap(raw);JSONArray out=new JSONArray();collect(value,out,0);return out;}
    private static void collect(Object v,JSONArray out,int depth)throws Exception {if(depth>5||out.length()>100)return;if(v instanceof JSONArray){JSONArray a=(JSONArray)v;for(int i=0;i<a.length();i++)collect(a.opt(i),out,depth+1);}else if(v instanceof JSONObject){JSONObject o=(JSONObject)v;if(o.has("us_id")&&o.optJSONObject("setting")!=null){out.put(o);return;}for(Iterator<String> i=o.keys();i.hasNext();){String k=i.next();Object child=o.opt(k);if(child instanceof JSONObject||child instanceof JSONArray)collect(child,out,depth+1);}}}
    static JSONObject owned(JSONArray list,String usid,String did)throws Exception {if(!usid.matches("[A-Za-z0-9_-]{1,96}"))throw new IOException("定时标识无效");for(int i=0;i<list.length();i++){JSONObject task=list.getJSONObject(i);if(usid.equals(task.optString("us_id"))){JSONObject setting=task.optJSONObject("setting");if(!ownName(task.optString("name"))||setting==null||!"set_properties".equals(setting.optString("on_method"))||!"set_properties".equals(setting.optString("off_method"))||!bound(setting.optJSONArray("on_param"),did,true)||!bound(setting.optJSONArray("off_param"),did,false))break;return task;}}throw new IOException("仅可修改家聚创建的定时，请刷新后重试");}
    static boolean ownName(String name){return name.startsWith("家聚 · ")||name.startsWith("家控 · ");}
    static String description(JSONObject setting){StringBuilder out=new StringBuilder();for(String kind:new String[]{"on","off"}){if(!enabled(setting,"enable_timer_"+kind))continue;String[] parts=setting.optString(kind+"_time").trim().split("\\s+");String text="按设备定时规则";if(parts.length==5&&parts[0].matches("[0-9]{1,2}")&&parts[1].matches("[0-9]{1,2}")&&"*".equals(parts[2])&&"*".equals(parts[3])){String week="每天";if(!"*".equals(parts[4])){StringBuilder days=new StringBuilder();String[] labels={"周日","周一","周二","周三","周四","周五","周六"};for(String day:parts[4].split(",")){if(!day.matches("[0-6]")){days.setLength(0);break;}if(days.length()>0)days.append('、');days.append(labels[Integer.parseInt(day)]);}week=days.length()>0?days.toString():"按设备重复规则";}text=String.format(Locale.ROOT,"%s %02d:%02d",week,Integer.parseInt(parts[1]),Integer.parseInt(parts[0]));}if(out.length()>0)out.append("；");out.append(text).append("on".equals(kind)?" 开灯":" 关灯");}return out.length()>0?out.toString():"暂无已启用的开关动作";}
    static boolean enabled(JSONObject o,String key){Object v=o.opt(key);return Boolean.TRUE.equals(v)||"1".equals(String.valueOf(v))||"true".equals(String.valueOf(v));}
    private static JSONArray params(String did,boolean on)throws Exception{return new JSONArray().put(new JSONObject().put("did",did).put("siid",2).put("piid",1).put("value",on));}
    private static boolean bound(JSONArray a,String did,boolean on){if(a==null||a.length()!=1)return false;JSONObject p=a.optJSONObject(0);return p!=null&&did.equals(p.optString("did"))&&p.optInt("siid")==2&&p.optInt("piid")==1&&Boolean.valueOf(on).equals(p.opt("value"));}
    private LightSchedules(){}
}
